INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Hat eine IPv4-Adresse immer 32 Bits insgesamt?', 2, '[{"text": "Ja", "correct": true, "because": "Feste Länge von IPv4"}, {"text": "Nein", "correct": false, "because": "Standarddefinition"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Hostbits hat /24?', 3, '[{"text": "8", "correct": true, "because": "32 - 24 = 8"}, {"text": "24", "correct": false, "because": "Das sind Netzwerkbits"}, {"text": "16", "correct": false, "because": "Falsche Aufteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /16 hat 16 Netzwerkbits. b) Hostbits sind immer 8.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hostbits variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Bitanzahl?', 4, '[{"text": "Netzwerkbits", "correct": false, "because": "Definiert Netz"}, {"text": "Hostbits", "correct": false, "because": "Definiert Geräte"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /32 Hostbits hat?', 2, '[{"text": "Nein", "correct": true, "because": "Alle 32 Bits sind Netzwerk"}, {"text": "Ja", "correct": false, "because": "Keine Hostbits übrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Netzwerkbits hat 255.255.255.240?', 3, '[{"text": "28", "correct": true, "because": "4 Bits für Hosts"}, {"text": "24", "correct": false, "because": "Zu wenig Bits"}, {"text": "32", "correct": false, "because": "Keine Hostbits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bitanzahlen sind möglich?', 5, '[{"text": "24 Netzwerkbits", "correct": true, "because": "8 Hostbits"}, {"text": "30 Netzwerkbits", "correct": true, "because": "2 Hostbits"}, {"text": "33 Netzwerkbits", "correct": false, "because": "Über 32"}, {"text": "15.5 Hostbits", "correct": false, "because": "Keine Dezimalwerte"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /8 hat 24 Hostbits. b) Netzwerkbits sind fix. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Netzwerkbits variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Bitanzahl?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Definiert Bits"}, {"text": "Gesamtbits", "correct": false, "because": "32 bei IPv4"}, {"text": "Betriebssystem", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat /16 16 Hostbits?', 2, '[{"text": "Ja", "correct": true, "because": "32 - 16 = 16"}, {"text": "Nein", "correct": false, "because": "Korrekte Aufteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Hostbits bleiben bei /20?', 4, '[{"text": "12", "correct": true, "because": "32 - 20 = 12"}, {"text": "20", "correct": false, "because": "Das sind Netzwerkbits"}, {"text": "8", "correct": false, "because": "Zu wenig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass /24 keine Hostbits hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "8 Hostbits übrig"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Bitaufteilung?', 3, '[{"text": "Netzwerkgröße", "correct": true, "because": "Bestimmt Hostbits"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /30 hat 2 Hostbits. b) Netzwerkbits sind immer 24.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Netzwerkbits variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bitanzahlen passen zu /28?', 5, '[{"text": "28 Netzwerkbits", "correct": true, "because": "Maske definiert"}, {"text": "4 Hostbits", "correct": true, "because": "32 - 28 = 4"}, {"text": "24 Netzwerkbits", "correct": false, "because": "Zu wenig"}, {"text": "8 Hostbits", "correct": false, "because": "Zu viel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Bitanzahl unwichtig?', 3, '[{"text": "Netzwerkbits", "correct": false, "because": "Definiert Netz"}, {"text": "Hostbits", "correct": false, "because": "Definiert Geräte"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat /8 24 Netzwerkbits?', 3, '[{"text": "Nein", "correct": true, "because": "Nur 8 Netzwerkbits"}, {"text": "Ja", "correct": false, "because": "Falsche Zählung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /31 1 Hostbit hat?', 2, '[{"text": "Ja", "correct": true, "because": "32 - 31 = 1"}, {"text": "Nein", "correct": false, "because": "Korrekte Aufteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Netzwerkbits hat 255.255.255.252?', 4, '[{"text": "30", "correct": true, "because": "2 Hostbits übrig"}, {"text": "24", "correct": false, "because": "Zu wenig"}, {"text": "32", "correct": false, "because": "Keine Hostbits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske hat 16 Hostbits?', 3, '[{"text": "/16", "correct": true, "because": "32 - 16 = 16"}, {"text": "/24", "correct": false, "because": "Nur 8 Hostbits"}, {"text": "/8", "correct": false, "because": "24 Hostbits"}]');
